function backspaceCompare(s, t) {
  function process(str) {
    const buffer = [];
    for (let i = 0; i < str.length; i++) {
      if (str[i] === '#') {
        if (buffer.length > 0) {
          buffer.pop();
        }
      } else {
        buffer.push(str[i]);
      }
    }
    return buffer.join('');
  }
  return process(s) === process(t);
}

function backspaceCompare(s, t) {
  let p1 = s.length - 1;
  let p2 = t.length - 1;
  let skips1 = 0;
  let skips2 = 0;

  while (p1 >= 0 || p2 >= 0) {
    while (p1 >= 0) {
      if (s[p1] === '#') {
        skips1++;
        p1--;
      } else if (skips1 > 0) {
        skips1--;
        p1--;
      } else {
        break;
      }
    }

    while (p2 >= 0) {
      if (t[p2] === '#') {
        skips2++;
        p2--;
      } else if (skips2 > 0) {
        skips2--;
        p2--;
      } else {
        break;
      }
    }

    const c1 = p1 >= 0 ? s[p1] : null;
    const c2 = p2 >= 0 ? t[p2] : null;

    if (c1 !== c2) {
      return false;
    }

    p1--;
    p2--;
  }

  return true;
}
